package com.company.platform.commerce;
import com.company.platform.commerce.domain.pricing.*; import com.company.platform.commerce.domain.product.*; import org.junit.jupiter.api.Test; import java.math.BigDecimal; import java.time.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*;
class CommerceDomainTest { @Test void moneyRejectsNegative(){assertThrows(IllegalArgumentException.class,()->new Money(new BigDecimal("-1"),Currency.getInstance("USD")));} @Test void priceCannotReactivateAfterExpiry(){var p=Price.create(UUID.randomUUID(),UUID.randomUUID(),new Money(BigDecimal.TEN,Currency.getInstance("USD")),Instant.now(),Instant.now().plusSeconds(60));p.activate();p.expire();assertEquals(PriceStatus.EXPIRED,p.status());assertThrows(IllegalStateException.class,p::activate);} @Test void sellableRequiresTenant(){assertThrows(IllegalArgumentException.class,()->SellableProduct.create(null,UUID.randomUUID(),UUID.randomUUID()));} }
